    r'^(?P<indent>\s*)(?:(?:const\s+)?(?:struct|unsigned|u8|u16|u32|__be16|__be32|__wsum|void)\s+)+
    (?P<var>\w+)\s*=\s*(?P<rhs>[^;]+);$',
    re.X)

def find_func_bounds(lines, idx):
    # find start: previous line at col0 ending with '{'
    start = idx
    while start > 0:
        if lines[start].startswith('{') or (lines[start].rstrip().endswith('{') and not lines[start].startswith(('\t',' '))):
            break
        start -= 1
    # find end: matching brace from start
    depth = 0
    i = start
    end = start
    while i < len(lines):
        depth += lines[i].count('{') - lines[i].count('}')
        if depth <= 0 and i > start:
            end = i
            break
        if depth <= 0 and i == start and '{' in lines[start]:
            # single-line function
            end = i
            break
        i += 1
    return start, min(end, len(lines)-1)

def scan_file(path):
